class QuestFieldActionConsistencyTests(unittest.TestCase):
 def test_two_source_locked_draft_entries(self):
  self.assertEqual(len(EXPECTED),2)
  for x in EXPECTED:
   self.assertEqual(next(e for e in L(x['plan'])['entries'] if e['id']==x['entry']['id']),x['entry'])
   self.assertEqual(L(x['plan'].replace('.json','.review.json'))['status'],'draft')
 def test_fifteen_shared_feature_anchors(self):
  self.assertEqual(len(ANCHORS),15)
  for a in ANCHORS:
   e=next(e for e in L(a['plan'])['entries'] if e['id']==a['id']);self.assertEqual(e['source_sha256'],a['source_sha256']);self.assertEqual(hashlib.sha256(e['translation'].encode()).hexdigest(),a['translation_sha256']);self.assertIn('场景动作',e['translation']);self.assertNotIn('场地行动',e['translation'])
 def test_review_without_recount(self):
  d=L('locales/zh-Hans/consistency-reviews/quest-ch02-followups.json');self.assertEqual((len(d['entries']),len(d['scopes'])),(201,11));self.assertEqual((d['new_translations'],d['new_context_entries'],d['translation_edits']),(0,0,2));self.assertEqual(sum(x['physical'] for x in d['scopes']),202)
  entries={}
  for b in L('locales/zh-Hans/translation-workflow.json')['batches']:entries.update({e['id']:e for e in L(b['plan']['path'])['entries']})
  for e in d['entries']:self.assertEqual(entries[e['id']]['source_sha256'],e['source_sha256']);self.assertEqual(hashlib.sha256(entries[e['id']]['translation'].encode()).hexdigest(),e['translation_sha256'])
  for flag in ['human_finalized','runtime_layout_approved','game_rendering_verified']:self.assertFalse(d[flag])
if __name__=='__main__':unittest.main()
